  [6650] = { "剣または短剣に毒を塗ります。毒は30分持続します。\n攻撃のたびに一定の確率で敵を毒に冒し、即座に10～30のダメージを与えます。", nil, 0x931dfb08, nil, "um" },
  [6653] = { "Dire Wolfを召喚/退散します。", "地上での移動速度が$N1%上昇します。", 0x6fa4e41c, 0x2195529a, "uu" },
  [6654] = { "Brown Wolfを召喚/退散します。", "地上での移動速度が$N1%上昇します。", 0x0cb06ca4, 0x2195529a, "uu" },
