  [6666] = { "飼いならした猫にSurvival Instinctのアビリティを教えます。Survival Instinctは敵をスタンさせて逃走を試み、敵に猫への攻撃をあきらめさせます。\n必要条件：\nペットのLevel 22以上", nil, 0x52fa73e9, nil, "um" },
  [6668] = { "空に花火を打ち上げます。花火は千の赤い星となって弾けます。", nil, 0xb5141a1b, nil, "um" },
  [6669] = { "敵から逃げます", nil, 0x67274bb4, nil, "um" },
