  [6725] = { "炎の柱を降らせ、選択した範囲のすべての敵に$N1のFireダメージを与え、さらに$D2の間、$D1ごとに$N2の追加ダメージを与えます。", nil, 0xf08ad6f8, nil, "um" },
  [6726] = { "敵を沈黙させ、$D1の間呪文を唱えられなくします。", "呪文を詠唱できません。", 0x92e27777, 0x6d133d61, "uu" },
  [6727] = { "食べないで。", nil, 0x0ed1fa1a, nil, "um" },
  [6728] = { "最大$D1の間、敵を竜巻で包みます。対象がダメージを受けると、閉じ込めている風から解放されます。", "スタンしています。", 0x9d0e8d01, 0x27f95286, "uu" },
