  [6749] = { nil, "スタンしています。", nil, 0x27f95286, "mu" },
  [6751] = { "$D2の間、$D1ごとに敵に$N1のNatureダメージを与えます。", "$D1ごとに$N1のNatureダメージを受けています。", 0xc14e209a, 0xf6322bec, "uu" },
  [6752] = { "攻撃命中時に対象を毒に冒す確率を追加します。", nil, 0xc0341f16, nil, "um" },
