  [6759] = { "ノリノリ！", nil, 0x35ce98f3, nil, "um" },
  [6760] = { "コンボポイントごとにダメージを与えるフィニッシュ技です。ダメージはAttack Powerによって増加します：\n $N1ポイント：$N2-$N3ダメージ\n $N4ポイント：$N5-$N6ダメージ\n $N7ポイント：$N8-$N9ダメージ\n $N10ポイント：$N11-$N12ダメージ\n $N13ポイント：$N14-$N15ダメージ", nil, 0xb268c10a, nil, "um" },
  [6761] = { "コンボポイントごとにダメージを与えるフィニッシュ技です。ダメージはAttack Powerによって増加します：\n $N1ポイント：$N2-$N3ダメージ\n $N4ポイント：$N5-$N6ダメージ\n $N7ポイント：$N8-$N9ダメージ\n $N10ポイント：$N11-$N12ダメージ\n $N13ポイント：$N14-$N15ダメージ", nil, 0xb268c10a, nil, "um" },
  [6762] = { "コンボポイントごとにダメージを与えるフィニッシュ技です。ダメージはAttack Powerによって増加します：\n $N1ポイント：$N2-$N3ダメージ\n $N4ポイント：$N5-$N6ダメージ\n $N7ポイント：$N8-$N9ダメージ\n $N10ポイント：$N11-$N12ダメージ\n $N13ポイント：$N14-$N15ダメージ", nil, 0xb268c10a, nil, "um" },
  [6767] = { "プレイヤーに紫の矢印で印をつけます。10分間持続します。", "Test of Loreに失敗しました！Mark of Shameを背負っています！恥を知りなさい！！", 0xb2d0023e, 0x465d39ab, "uu" },
  [6768] = { "フェイントを行います。ダメージは与えませんが脅威が中程度下がり、敵に攻撃されにくくなります。", nil, 0x4ffd4309, nil, "um" },
  [6770] = { "最大$D1の間、対象を行動不能にします。戦闘中でないHumanoidsにのみ有効です。ダメージを受けると効果が解けます。一度に気絶させられる対象は1体だけです。Stealthは解除されません。", "行動不能です。", 0x6569e326, 0x147cb83f, "uu" },
  [6772] = { "敵の人型を転倒させ、$N1のダメージを与えて$D1の間ノックダウンさせます。コンボポイントを$N3獲得します。", nil, 0x296ab555, nil, "um" },
  [6774] = { "近接攻撃速度を$N1%上げるフィニッシュ技です。コンボポイントが多いほど長く持続します：\n1ポイント：$N3秒\n2ポイント：$N5秒\n3ポイント：$N7秒\n4ポイント：$N9秒\n5ポイント：$N11秒", "近接攻撃速度が$N1%上昇しています。", 0x9e71ebcf, 0xd4718a15, "uu" },
