  [6780] = { "対象に$N1のNatureダメージを与えます。", nil, 0xb57329ad, nil, "um" },
  [6783] = { "ドルイドが忍び歩きできるようになりますが、移動速度が$N1%低下します。解除するまで持続します。", "隠密状態です。移動速度が$N1%低下しています。", 0x17709e32, 0x2854da84, "uu" },
  [6785] = { "対象を切り裂き、ダメージの$N1%に147を加えたダメージを与えます。忍び歩き中で、対象の背後にいる必要があります。コンボポイントを$N3獲得します。", nil, 0x719163b4, nil, "um" },
  [6787] = { "対象を切り裂き、ダメージの$N1%に217を加えたダメージを与えます。忍び歩き中で、対象の背後にいる必要があります。コンボポイントを$N3獲得します。", nil, 0xba9a1921, nil, "um" },
  [6788] = { nil, "Power Word: Shieldを受けられません。", nil, 0xba3bc5e1, "mu" },
  [6789] = { "敵の対象を$D1の間恐怖で逃げ回らせ、$N2のShadowダメージを与えます。術者は与えたダメージの100%を体力として得ます。", "恐れおののいています。", 0x87b4271e, 0xa7c416d7, "uu" },
  [6795] = { "対象を挑発して自分を攻撃させます。ただし、対象がすでに自分を攻撃している場合は効果がありません。", nil, 0x71de38fd, nil, "um" },
