  [6909] = { "敵に$D1の間呪いをかけ、攻撃時に$N2%の確率で$N3のダメージを受けるようにします。", "攻撃時に$N1%の確率で$N2のダメージを受けます。", 0xb2cad783, 0xfce0ca62, "uu" },
