  [6921] = { "$D1の間、術者が与えるPhysicalダメージを$N1増加させ、移動速度を$N2%上昇させます。また、最初に攻撃が命中した敵に呪いをかけ、$D2の間、その敵が与えるPhysicalダメージを$N4、魔法ダメージを$N5減少させ、受けるPhysicalダメージを$N6増加させます。", "移動速度が$N1%上昇しています。\n与える物理ダメージが$N2増加しています。", 0x6f84ccf6, 0x4079718d, "uu" },
  [6922] = { nil, "受ける物理ダメージが$N1増加しています。\n与える物理ダメージが$N2減少しています。\n与える魔法ダメージが$N3減少しています。", nil, 0x367d0c24, "mu" },
  [6927] = { "ステルス状態から攻撃した際、敵に通常ダメージに加えて$N1を与え、$D1スタンさせます。コンボポイントを$N3獲得します。", "スタンしています。", 0xaa05c18c, 0x27f95286, "uu" },
  [6940] = { "パーティーメンバーにBlessingをかけ、一撃ごとに受けるダメージのうち$N1を術者に移します。効果時間は$D1です。プレイヤーにかけられるBlessingは、パラディン一人につき同時に一つだけです。", "攻撃を受けるたびに、受けたダメージのうち$N1をパラディンに移します。", 0xc63d07ed, 0x05bd038b, "uu" },
  [6942] = { "敵を沈黙させ、$D1の間呪文を唱えられなくします。", "呪文を詠唱できません。", 0x92e27777, 0x6d133d61, "uu" },
  [6945] = { nil, "スタンしています。", nil, 0x27f95286, "mu" },
  [6946] = { nil, "心臓が弱っています……。", nil, 0x6b9b1659, "mu" },
  [6949] = { "敵に氷の矢を放ち、$N1のFrostダメージを与えます。", nil, 0x533ecc6c, nil, "um" },
  [6950] = { "$D1の間、敵のアーマーを$N1低下させます。効果を受けている間、対象はステルスや透明化を使用できません。", "アーマーが$N1低下しています。\n隠密や透明化を使用できません。", 0x8b009da8, 0x0730b87e, "uu" },
  [6951] = { "$D1の間、敵の筋力を$N1低下させます。", "筋力が$N1低下しています。", 0x9104e68d, 0x6e27e536, "uu" },
  [6957] = { "$D1の間、味方の筋力を$N1増加させます。", "筋力が$N1増加しています。", 0xcfb0df5d, 0x90d8a2f8, "uu" },
  [6958] = { "敵の体力を$N1吸収し、術者に移します。", nil, 0x922bf65a, nil, "um" },
  [6960] = { "味方を$D1持続する電撃の盾で包み、近接攻撃してきた相手に$N2のNatureダメージを与えます。", "近接攻撃してきた相手に$N1のNatureダメージを与えます。", 0x29ca017d, 0xd89ce264, "uu" },
