  [6980] = { "敵に炎の射撃を放ち、$N1の追加ダメージを与え、ダメージを火属性にします。", nil, 0xd7627676, nil, "um" },
  [6982] = { "周囲の敵をスタンさせ、$D1の間移動も攻撃もできなくします。", "スタンしています。", 0x3546cc6b, 0x27f95286, "uu" },
