  [6985] = { "敵に冷気の射撃を放ち、$N1の追加冷気ダメージを与え、敵の移動速度を$N2%低下させます。", nil, 0x88663c52, nil, "um" },
  [6991] = { "選択したアイテムをペットに食べさせます。ペットに餌を与えると幸福度が上がります。ペットのレベルに近い食べ物を使うほど、良い結果になります。", nil, 0x118e6cd5, nil, "um" },
